const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s),overlay=$('#overlay');
let W=0,H=0,DPR=1,run=false,dead=false,lane=1,playerX=1,jumpT=0,slideT=0,stepT=0,coins=0,distance=0,speed=18,spawnIn=1.1,last=0,elapsed=0,objects=[],particles=[],record=+(localStorage.getItem('neonBest')||0),shake=0;
$('#best').textContent=String(record).padStart(4,'0')+' m';
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
const rand=(a,b)=>a+Math.random()*(b-a),pick=a=>a[Math.floor(Math.random()*a.length)],clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function project(x,y,d){const f=Math.min(H*.94,W*1.08),den=Math.max(2,d+8),s=f/den,horizon=H*(W<600?.29:.27);return{x:W/2+x*s,y:horizon+s*(3.8-y),s}}
function poly(points,fill,stroke=null,lw=1){ctx.beginPath();points.forEach((p,i)=>{const q=project(p[0],p[1],p[2]);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
function quad(x1,y1,d1,x2,y2,d2,x3,y3,d3,x4,y4,d4,color){poly([[x1,y1,d1],[x2,y2,d2],[x3,y3,d3],[x4,y4,d4]],color)}
function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function background(){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#83c8d6');sky.addColorStop(.42,'#d9d3b9');sky.addColorStop(1,'#e4b987');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // late-night city glow and distant skyline
 const horizon=H*(W<600?.29:.27),glow=ctx.createRadialGradient(W*.5,horizon,0,W*.5,horizon,W*.55);glow.addColorStop(0,'#ffdfa1a8');glow.addColorStop(1,'#ffc87600');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H*.7);
 let x=-12;while(x<W+20){const seed=Math.sin(x*12.98)*43758.5,unit=seed-Math.floor(seed),bw=22+unit*42,bh=35+((seed*19)%80+80)%80;ctx.fillStyle=unit>.5?'#5e8290':'#718f97';ctx.fillRect(x,horizon-bh,bw,bh);ctx.fillStyle='#ffdfa05e';for(let wy=horizon-bh+8;wy<horizon-5;wy+=13)for(let wx=x+7;wx<x+bw-4;wx+=12)if(Math.sin(wx*3+wy*7)>.1)ctx.fillRect(wx,wy,3,5);x+=bw+3}
 // overhead metro gantries
 for(let side of [-1,1]){const xx=side===-1?W*.04:W*.96;ctx.fillStyle='#476b76';ctx.fillRect(xx-4,horizon-42,8,47);ctx.fillRect(side<0?0:W*.79,horizon-42,W*.21,5)}
 // track bed
 const far=project(0,0,160),near=project(0,0,-1);const lfar=project(-3.65,0,160),rfar=project(3.65,0,160),lnear=project(-3.65,0,-1),rnear=project(3.65,0,-1);ctx.fillStyle='#52636a';ctx.beginPath();ctx.moveTo(lfar.x,lfar.y);ctx.lineTo(rfar.x,rfar.y);ctx.lineTo(rnear.x,rnear.y);ctx.lineTo(lnear.x,lnear.y);ctx.fill();
 // colored platform edges
 quad(-3.78,0,160,-3.65,0,160,-3.65,0,-1,-3.78,0,-1,'#e4a95c');quad(3.65,0,160,3.78,0,160,3.78,0,-1,3.65,0,-1,'#e4a95c');
 // track sleepers and steel rails
 for(let d=158;d>-1;d-=3.3){const z=d-distance%3.3;if(z<-.8)continue;for(let laneI=0;laneI<3;laneI++){const cx=(laneI-1)*2.2;quad(cx-1.08,0,z,cx+1.08,0,z,cx+1.08,0,z-.72,cx-1.08,0,z-.72,z<10?'#555c60':'#485258');for(const off of [-.86,.86]){const rail=project(cx+off,.11,z);ctx.fillStyle='#b8c2bb';ctx.beginPath();ctx.ellipse(rail.x,rail.y,Math.max(1,rail.s*.09),Math.max(1,rail.s*.04),0,0,Math.PI*2);ctx.fill()}}}
 for(let xline of [-2.2,0,2.2]){quad(xline-.04,0,160,xline+.04,0,160,xline+.04,0,-1,xline-.04,0,-1,'#87908b')}
 // roadside lamps, poles and signs
 for(let d=120;d>5;d-=19){for(let side of [-1,1]){const x=side*5.2,p=project(x,0,d),top=project(x,3.8,d);ctx.strokeStyle='#465861';ctx.lineWidth=Math.max(1,p.s*.055);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(top.x,top.y);ctx.stroke();ctx.fillStyle='#ffe9ae';ctx.beginPath();ctx.ellipse(top.x+side*top.s*.25,top.y,Math.max(1,top.s*.18),Math.max(1,top.s*.08),0,0,Math.PI*2);ctx.fill();const bx=project(side*7.9,0,d-4),bt=project(side*7.9,4+Math.sin(d)*1,d-4);ctx.fillStyle='#667b7c';ctx.fillRect(bx.x-bx.s*.07,bt.y,bx.s*.14,bx.y-bt.y);ctx.fillStyle=side<0?'#fc845f':'#42daca';ctx.fillRect(bt.x-bt.s*.58,bt.y-bt.s*.3,bt.s*1.16,bt.s*.6)}}
}
function box(x,d,w,h,depth,color,topColor=color,sideColor=null){const a=x-w/2,b=x+w/2,z=d,back=z-depth;poly([[a,0,z],[b,0,z],[b,h,z],[a,h,z]],color);poly([[a,h,z],[b,h,z],[b,h,back],[a,h,back]],topColor);poly([[b,0,z],[b,0,back],[b,h,back],[b,h,z]],sideColor||shade(color,-22));poly([[a,0,back],[b,0,back],[b,h,back],[a,h,back]],shade(color,-32));}
function shade(hex,delta){let n=parseInt(hex.slice(1),16);let r=clamp((n>>16)+delta,0,255),g=clamp(((n>>8)&255)+delta,0,255),b=clamp((n&255)+delta,0,255);return`rgb(${r},${g},${b})`}
function drawObstacle(o){const x=(o.lane-1)*2.2,d=o.d;if(o.type==='train'){box(x,d,1.8,2.7,7.2,'#326c80','#5bafba','#244958');for(let i=0;i<3;i++){const p=project(x-.55+i*.55,2.08,d-.08);ctx.fillStyle=i===1?'#e6f4cc':'#9ae4df';ctx.beginPath();ctx.roundRect(p.x-p.s*.19,p.y-p.s*.2,p.s*.38,p.s*.35,p.s*.04);ctx.fill()}const front=project(x,1.1,d-.1);ctx.fillStyle='#ffd16a';ctx.beginPath();ctx.arc(front.x,front.y,Math.max(2,front.s*.1),0,7);ctx.fill();
 }else if(o.type==='barrier'){box(x,d,1.72,.92,.6,'#ef785d','#ffb46e','#c75053');const p=project(x,.66,d-.32);ctx.fillStyle='#fff0ce';ctx.save();ctx.translate(p.x,p.y);ctx.rotate(-.16);ctx.fillRect(-p.s*.44,-p.s*.07,p.s*.88,p.s*.15);ctx.restore();for(const dx of [-.63,.63])box(x+dx,d+.05,.14,.42,.18,'#394d53','#72868a')
 }else if(o.type==='gate'){box(x,d,1.8,2.2,.42,'#ecbd5d','#ffe296','#ce8846');const p=project(x,1.36,d-.24);ctx.fillStyle='#263a49';ctx.beginPath();ctx.roundRect(p.x-p.s*.62,p.y-p.s*.22,p.s*1.24,p.s*.46,p.s*.12);ctx.fill();for(let i=0;i<3;i++){const q=project(x-.42+i*.42,1.36,d-.25);ctx.fillStyle='#ffcf56';ctx.beginPath();ctx.arc(q.x,q.y,q.s*.065,0,7);ctx.fill()}
 }else{const p=project(x,.5,d);ctx.fillStyle='#fb8057';ctx.beginPath();ctx.ellipse(p.x,p.y,p.s*.55,p.s*.5,0,0,7);ctx.fill();ctx.fillStyle='#ffc06b';ctx.beginPath();ctx.ellipse(p.x,p.y-p.s*.23,p.s*.35,p.s*.2,0,0,7);ctx.fill()}}
function drawCoin(o){const p=project((o.lane-1)*2.2,o.y||.92,o.d);const r=Math.max(2,p.s*.2);ctx.save();ctx.translate(p.x,p.y);ctx.scale(.72+Math.abs(Math.sin(elapsed*6+o.phase))*.28,1);ctx.fillStyle='#ffc83d';ctx.strokeStyle='#fff2a1';ctx.lineWidth=Math.max(1,p.s*.045);ctx.beginPath();ctx.arc(0,0,r,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#fff1ab';ctx.font=`900 ${Math.max(5,r*1.1)}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✦',0,1);ctx.restore()}

function drawRunner(){const airborne=jumpT>0,alt=airborne?Math.sin((1-jumpT/.82)*Math.PI)*1.75:0,sliding=slideT>0;const p=project(playerX,alt,-.28),s=p.s,lean=Math.sin(stepT*10)*.06;ctx.save();ctx.globalAlpha=.24;ctx.fillStyle='#182a32';ctx.beginPath();ctx.ellipse(p.x,p.y+5,s*.51,s*.16,0,0,7);ctx.fill();ctx.restore();
 const legSwing=Math.sin(stepT*11)*.23,bodyY=p.y-s*(sliding?.75:1.75),scale=sliding?.72:1;
 // feet and legs
 ctx.lineCap='round';ctx.lineJoin='round';for(let i=0;i<2;i++){let off=i?1:-1;let swing=airborne?off*.15:legSwing*off;const hipX=p.x+off*s*.12,hipY=bodyY+s*.56*scale,kneeX=hipX+s*swing*.48,kneeY=p.y-s*(.58+alt*.06),footX=hipX+s*swing,footY=p.y-s*.1;ctx.strokeStyle='#25394e';ctx.lineWidth=s*.17;ctx.beginPath();ctx.moveTo(hipX,hipY);ctx.lineTo(kneeX,kneeY);ctx.lineTo(footX,footY);ctx.stroke();ctx.strokeStyle='#ec8756';ctx.lineWidth=s*.13;ctx.beginPath();ctx.moveTo(footX-s*.08,footY);ctx.lineTo(footX+s*.13,footY+s*.015);ctx.stroke()}
 // backpack
 rounded(p.x-s*.36,bodyY+s*.07*scale,s*.22,s*.58*scale,s*.08,'#f28a50');
 // torso
 ctx.fillStyle='#16a99d';ctx.beginPath();ctx.moveTo(p.x-s*.27,bodyY+s*.03*scale);ctx.lineTo(p.x+s*.27,bodyY+s*.03*scale);ctx.lineTo(p.x+s*.34,bodyY+s*.58*scale);ctx.lineTo(p.x-s*.33,bodyY+s*.58*scale);ctx.closePath();ctx.fill();ctx.fillStyle='#55eee0';ctx.fillRect(p.x-s*.035,bodyY+s*.08*scale,s*.07,s*.46*scale);
 // arms pumping
 for(let i=0;i<2;i++){let off=i?1:-1,arm=Math.sin(stepT*11+off*1.3)*.22;ctx.strokeStyle='#16a99d';ctx.lineWidth=s*.14;ctx.beginPath();ctx.moveTo(p.x+off*s*.23,bodyY+s*.14*scale);ctx.lineTo(p.x+off*s*(.37+arm*.2),bodyY+s*(.34+arm)*scale);ctx.stroke();ctx.fillStyle='#cb7653';ctx.beginPath();ctx.arc(p.x+off*s*(.37+arm*.2),bodyY+s*(.34+arm)*scale,s*.07,0,7);ctx.fill()}
 // neck, face, hair and cap
 ctx.fillStyle='#bd7554';ctx.fillRect(p.x-s*.095,bodyY-s*.09,s*.19,s*.17);ctx.fillStyle='#e2a174';ctx.beginPath();ctx.ellipse(p.x,bodyY-s*.24,s*.235,s*.27,0,0,7);ctx.fill();ctx.fillStyle='#24354a';ctx.beginPath();ctx.arc(p.x,bodyY-s*.31,s*.245,Math.PI,0);ctx.lineTo(p.x+s*.24,bodyY-s*.32);ctx.quadraticCurveTo(p.x,bodyY-s*.54,p.x-s*.24,bodyY-s*.32);ctx.fill();ctx.fillStyle='#e6f4ee';ctx.beginPath();ctx.arc(p.x+s*.08,bodyY-s*.25,s*.023,0,7);ctx.fill();
 // stripe on jacket
 ctx.fillStyle='#ffcf56';ctx.fillRect(p.x-s*.24,bodyY+s*.41*scale,s*.48,s*.045)}
function burst(x,y,color){for(let i=0;i<9;i++)particles.push({x,y,vx:rand(-90,90),vy:rand(-130,20),life:.55,max:.55,color})}
function addWave(){const blocked=Math.floor(Math.random()*3),types=['train','barrier','gate','barrel'];const typ=pick(types);objects.push({kind:'obstacle',type:typ,lane:blocked,d:76});const safe=[0,1,2].filter(v=>v!==blocked);const coinLane=pick(safe);for(let i=0;i<6;i++)objects.push({kind:'coin',lane:coinLane,d:48-i*5.1,y:.88+(i%2)*.08,phase:i*.7});if(Math.random()<.32){const other=safe.find(v=>v!==coinLane);objects.push({kind:'obstacle',type:pick(['barrier','barrel']),lane:other,d:105})}}
function action(name){if(!run)return;if(name==='left')lane=Math.max(0,lane-1);if(name==='right')lane=Math.min(2,lane+1);if(name==='jump'&&jumpT<=0&&slideT<=0)jumpT=.82;if(name==='slide'&&jumpT<=0)slideT=.72}
function begin(){run=true;dead=false;lane=1;playerX=1;coins=0;distance=0;speed=18;elapsed=0;spawnIn=.5;jumpT=slideT=0;objects=[];particles=[];overlay.classList.add('hidden');$('#distance').textContent='0000';$('#coins').textContent='00';last=performance.now()}
function endRun(){if(dead)return;run=false;dead=true;shake=.45;record=Math.max(record,Math.floor(distance));localStorage.setItem('neonBest',record);$('#best').textContent=String(record).padStart(4,'0')+' m';$('#eyebrow').textContent='THE TRACK ALWAYS WINS';$('#title').innerHTML='NICE<br><em>RUN!</em>';$('#description').innerHTML=`You dashed <b style="color:#fff">${Math.floor(distance)} m</b> and collected <b style="color:#ffcf56">${coins} coins</b>. Ready to beat your best?`;$('#play').textContent='RUN IT BACK  →';overlay.classList.add('gameover');overlay.classList.remove('hidden')}
$('#play').addEventListener('click',begin);
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup','arrowdown',' '].includes(k))e.preventDefault();if(!run){if(k==='enter'||k===' ')begin();return}if(k==='arrowleft'||k==='a')action('left');if(k==='arrowright'||k==='d')action('right');if(k==='arrowup'||k==='w'||k===' ')action('jump');if(k==='arrowdown'||k==='s')action('slide')});
document.querySelectorAll('.ctrl').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();action(b.dataset.action)})});let touchStart=null;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')touchStart={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointerup',e=>{if(!touchStart)return;const dx=e.clientX-touchStart.x,dy=e.clientY-touchStart.y;touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))<24)return;if(Math.abs(dx)>Math.abs(dy))action(dx<0?'left':'right');else action(dy<0?'jump':'slide')});
function update(dt){elapsed+=dt;if(!run){stepT+=dt*3;return}speed=Math.min(31,18+distance*.013);distance+=speed*dt;$('#distance').textContent=String(Math.floor(distance)).padStart(4,'0');stepT+=dt*(speed*.52);if(jumpT>0)jumpT=Math.max(0,jumpT-dt);if(slideT>0)slideT=Math.max(0,slideT-dt);playerX+=(lane-playerX)*Math.min(1,dt*12);spawnIn-=dt;if(spawnIn<=0){addWave();spawnIn=rand(1.15,1.52)}
 for(const o of objects)o.d-=speed*dt;
 for(const o of objects){if(o.kind==='coin'&&o.d<1.15&&o.d>-.8&&Math.abs(playerX-o.lane)<.55){o.d=-99;coins++;$('#coins').textContent=String(coins).padStart(2,'0');const p=project((o.lane-1)*2.2,o.y||.9,0);burst(p.x,p.y,'#ffd34e')}else if(o.kind==='obstacle'&&o.d<.8&&o.d>-.2&&Math.abs(playerX-o.lane)<.54){const safe=(o.type==='gate'&&slideT>.16)||(o.type==='barrier'&&jumpT>.17)||(o.type==='barrel'&&jumpT>.17);if(!safe){endRun();break}else{o.d=-99}}}
 objects=objects.filter(o=>o.d>-9);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);if(shake>0)shake=Math.max(0,shake-dt)}

