function render(){ctx.save();if(shake>0)ctx.translate(rand(-6,6)*shake,rand(-4,4)*shake);background();const sorted=objects.slice().sort((a,b)=>b.d-a.d);for(const o of sorted){if(o.d>175||o.d<-.9)continue;if(o.kind==='coin')drawCoin(o);else drawObstacle(o)}drawRunner();for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,3,0,7);ctx.fill()}ctx.globalAlpha=1;ctx.restore()}
