 function endRun(){if(dead)return;run=false;dead=true;shake=.45;record=Math.max(record,Math.floor(distance));localStorage.setItem('neonBest',record);$('#best').textContent=String(record).padStart(4,'0')+' m';$('#eyebrow').textContent='THE TRACK ALWAYS WINS';$('#title').innerHTML='NICE<br><em>RUN!</em>';$('#description').innerHTML=`You dashed <b style="color:#fff">${Math.floor(distance)} m</b> and collected <b style="color:#ffcf56">${coins} coins</b>. Ready to beat your best?`;$('#play').textContent='RUN IT BACK  →';overlay.classList.add('gameover');overlay.classList.remove('hidden')}
 $('#play').addEventListener('click',begin);addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup','arrowdown',' '].includes(k))e.preventDefault();if(!run){if(k==='enter'||k===' ')begin();return}if(k==='arrowleft'||k==='a')action('left');if(k==='arrowright'||k==='d')action('right');if(k==='arrowup'||k==='w'||k===' ')action('jump');if(k==='arrowdown'||k==='s')action('slide')});document.querySelectorAll('.ctrl').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();action(b.dataset.action)}));let touchStart=null;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')touchStart={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointerup',e=>{if(!touchStart)return;const dx=e.clientX-touchStart.x,dy=e.clientY-touchStart.y;touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))<24)return;if(Math.abs(dx)>Math.abs(dy))action(dx<0?'left':'right');else action(dy<0?'jump':'slide')});
 function update(dt){elapsed+=dt;if(!run){stepT+=dt*3;return}speed=Math.min(31,18+distance*.013);distance+=speed*dt;$('#distance').textContent=String(Math.floor(distance)).padStart(4,'0');stepT+=dt*(speed*.52);if(jumpT>0)jumpT=Math.max(0,jumpT-dt);if(slideT>0)slideT=Math.max(0,slideT-dt);playerX+=(lane-playerX)*Math.min(1,dt*12);spawnIn-=dt;if(spawnIn<=0){addWave();spawnIn=rand(1.15,1.52)}for(const o of objects)o.d-=speed*dt;
  for(const o of objects){if(o.kind==='coin'&&o.d<1.15&&o.d>-.8&&Math.abs(playerX-o.lane)<.55){o.d=-99;coins++;$('#coins').textContent=String(coins).padStart(2,'0');const p=project((o.lane-1)*2.2,o.y||.9,0);burst(p.x,p.y,'#ffd34e')}else if(o.kind==='obstacle'&&o.d<.8&&o.d>-.2&&Math.abs(playerX-o.lane)<.54){const safe=(o.type==='gate'&&slideT>.16)||(o.type==='barrier'&&jumpT>.17)||(o.type==='barrel'&&jumpT>.17);if(!safe){endRun();break}else{o.d=-99}}}objects=objects.filter(o=>o.d>-9);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);if(shake>0)shake=Math.max(0,shake-dt)}
